CREATE DATABASE IF NOT EXISTS tasks_today_tsa3 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tasks_today_tsa3;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,full_name VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',task_date DATE NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX tasks_task_date_index(task_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
